//! Golden `.vaultbak` and `.vaultarc` written by release 0.60.0 (R20), beside the 0.42.4 pair in
//! `golden_backups.rs`. Both files were produced by the published 0.60.0 CLI from the vault in
//! `vault-core/tests/fixtures/vault-0.60.x/` (`unv backup export` and `unv backup archive`, backup
//! password below) and are never regenerated by CI. If a test here fails, the envelope or the
//! database format moved and a migration is owed, not a new fixture.
//!
//! One test function on purpose: `access::set_paths` is a write-once `OnceLock` per process.

use std::path::{Path, PathBuf};
use unv_app::{access, backup};

const PW: &str = "golden-fixture-password";
const BAK_PW: &str = "golden-backup-password-1";

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/backups-0.60.x")
}

fn temp(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("unv-golden060-bak-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

fn open_local(pw: &str) -> access::Access {
    access::open_access(&access::AuthOpts {
        server: None,
        password: Some(pw),
        user: None,
        token: None,
        session_token: None,
        totp: None,
        init: false,
        bridge: unv_app::access::Bridge::Off,
    })
    .expect("open local vault")
}

#[test]
fn backups_written_by_0_60_restore_with_their_entries_and_refuse_a_wrong_password() {
    let dir = temp("restore");
    let db = dir.join("vault.db");
    let salt = dir.join("vault.salt");
    access::set_paths(Some(db.clone()), None);

    // The archive brings back both files.
    backup::restore_archive(
        &fixture().join("golden.vaultarc"),
        Some(BAK_PW),
        false,
        true,
    )
    .expect("0.60.0 archive must restore");
    assert!(db.exists() && salt.exists());
    let key = vault_core::derive_key(PW, &std::fs::read(&salt).unwrap()).unwrap();
    let conn = vault_core::open_db(&db, &key).expect("master password opens restored vault");
    assert!(vault_core::verify_vault_integrity(&conn).unwrap());
    let v = vault_core::load_vault(&conn).unwrap().unwrap();
    assert_eq!(v["api_keys"].as_array().unwrap().len(), 2);
    drop(conn);

    // The envelope replaces an emptied vault, so the count proves the import did the work.
    let acc = open_local(PW);
    acc.save(&serde_json::json!({ "api_keys": [], "projects": [], "user_categories": [] }))
        .unwrap();
    backup::import(&acc, &fixture().join("golden.vaultbak"), Some(BAK_PW), true)
        .expect("0.60.0 backup must import");
    let v = acc.load_vault().unwrap();
    let names: Vec<&str> = v["api_keys"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| e["provider"].as_str().unwrap())
        .collect();
    assert_eq!(names.len(), 2, "{names:?}");
    assert!(names.contains(&"Golden GitHub") && names.contains(&"Golden Stripe"));

    // Control: the wrong password is refused and nothing is replaced.
    let err = backup::import(
        &acc,
        &fixture().join("golden.vaultbak"),
        Some("not-the-backup-password"),
        true,
    )
    .unwrap_err();
    assert_eq!(err.code, unv_app::error::Code::Denied, "{err}");
    assert_eq!(
        acc.load_vault().unwrap()["api_keys"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    let _ = std::fs::remove_dir_all(&dir);
}
